    @Autowired
    private AnnouncementRepo announcementRepo;

    @Autowired
    private UsersRepo usersRepo;

    @Autowired
    private NotificationService notificationService;

    public Page<StaffAnnouncementCardDTO> getAnnouncementCards(Pageable pageable) {
        return announcementRepo.findAllByOrderByIdDesc(pageable)
                .map(this::toCardDTO);
    }

    public Page<StaffAnnouncementCardDTO> searchAnnouncementCards(Pageable pageable,
                                                                  String keyword,
                                                                  String departmentId) {
        String normalizedKeyword = normalizeFilterValue(keyword);
        String normalizedDepartmentId = normalizeFilterValue(departmentId);

        return announcementRepo.searchAnnouncements(normalizedKeyword, normalizedDepartmentId, pageable)
                .map(this::toCardDTO);
    }

    @Transactional
    public boolean updateAnnouncement(String announcementId, String title, String content, Users staff) {
        if (staff == null || announcementId == null || announcementId.isBlank()) {
            return false;
        }

        Announcement announcement = announcementRepo.findById(announcementId.trim()).orElse(null);
        if (announcement == null || !canManage(announcement, staff)) {
            return false;
        }

        String safeContent = content == null ? "" : content.trim();
        if (safeContent.isBlank()) {
            return false;
        }

        String safeTitle = title == null ? "" : title.trim();
        announcement.setTitle(safeTitle.isBlank() ? null : safeTitle);
        announcement.setContent(safeContent);
        announcementRepo.save(announcement);
        return true;
    }

    @Transactional
    public boolean deleteAnnouncement(String announcementId, Users staff) {
        if (staff == null || announcementId == null || announcementId.isBlank()) {
            return false;
        }

        Announcement announcement = announcementRepo.findById(announcementId.trim()).orElse(null);
        if (announcement == null || !canManage(announcement, staff)) {
            return false;
        }

        announcementRepo.delete(announcement);
        return true;
    }

    @Transactional
    public boolean createAnnouncement(String title, String content, Users staff, List<String> receiverDepartmentIds) {
        if (staff == null) {
            return false;
        }

        String safeContent = content == null ? "" : content.trim();
        if (safeContent.isBlank()) {
            return false;
        }

        String safeTitle = title == null ? "" : title.trim();

        Announcement announcement = new Announcement();
        announcement.setId(generateAnnouncementId());
        announcement.setTitle(safeTitle.isBlank() ? null : safeTitle);
        announcement.setContent(safeContent);
        announcement.setUser(staff);

        announcementRepo.save(announcement);

        List<String> normalizedDepartmentIds = normalizeDepartmentIds(receiverDepartmentIds);
        if (!normalizedDepartmentIds.isEmpty()) {
            List<Users> studentReceivers = usersRepo.findByRoleAndDepartment_IdIn("ROLE_STUDENT", normalizedDepartmentIds);
            notificationService.notifyNewAnnouncement(announcement, studentReceivers);
        }

        return true;
    }

    private StaffAnnouncementCardDTO toCardDTO(Announcement announcement) {
        StaffAnnouncementCardDTO dto = new StaffAnnouncementCardDTO();
        dto.setId(announcement.getId());
        dto.setTitle((announcement.getTitle() == null || announcement.getTitle().isBlank()) ? "Thong bao" : announcement.getTitle());
        dto.setContent(announcement.getContent() == null ? "" : announcement.getContent());

        if (announcement.getUser() != null) {
            dto.setAuthorName(announcement.getUser().getFullName());
            if (announcement.getUser().getDepartment() != null) {
                dto.setDepartmentName(announcement.getUser().getDepartment().getName());
            }
        }

        if (dto.getAuthorName() == null || dto.getAuthorName().isBlank()) {
            dto.setAuthorName("Phong ban");
        }
        if (dto.getDepartmentName() == null || dto.getDepartmentName().isBlank()) {
            dto.setDepartmentName("Phong ban");
        }

        dto.setDateLabel(resolveDateLabel(announcement.getId()));
        return dto;
    }

    private String resolveDateLabel(String announcementId) {
        if (announcementId == null || announcementId.isBlank()) {
            return "--/--/----";
        }

        Matcher matcher = DATE_IN_ID_PATTERN.matcher(announcementId);
        if (!matcher.find()) {
            return "--/--/----";
        }

        try {
            LocalDate parsed = LocalDate.parse(matcher.group(1), SOURCE_DATE_FORMAT);
            return parsed.format(TARGET_DATE_FORMAT);
        } catch (DateTimeParseException ex) {
            return "--/--/----";
        }
    }

    private String normalizeFilterValue(String value) {
        if (value == null || value.isBlank()) {
            return null;
        }
        return value.trim();
    }

    private boolean canManage(Announcement announcement, Users staff) {
        if (announcement == null || announcement.getUser() == null || staff == null) {
            return false;
        }

        if (announcement.getUser().getId() != null && announcement.getUser().getId().equals(staff.getId())) {
            return true;
        }

        if (announcement.getUser().getDepartment() == null || staff.getDepartment() == null) {
            return false;
        }

        return announcement.getUser().getDepartment().getId().equals(staff.getDepartment().getId());
    }

    private String generateAnnouncementId() {
        String prefix = "ANN_" + LocalDateTime.now().format(ID_DATE_FORMAT) + "_";
        String candidate = prefix + ThreadLocalRandom.current().nextInt(100, 1000);
        while (announcementRepo.existsById(candidate)) {
            candidate = prefix + ThreadLocalRandom.current().nextInt(100, 1000);
        }
        return candidate;
    }

    private List<String> normalizeDepartmentIds(List<String> departmentIds) {
        if (departmentIds == null || departmentIds.isEmpty()) {
            return List.of();
        }

        LinkedHashSet<String> normalized = new LinkedHashSet<>();
        for (String departmentId : departmentIds) {
            if (departmentId != null && !departmentId.isBlank()) {
                normalized.add(departmentId.trim());
            }
        }
        return new ArrayList<>(normalized);
    }
}

package nvt.vn.ute_forum.service;

import nvt.vn.ute_forum.model.Notification;
import nvt.vn.ute_forum.model.ReactionType;
import nvt.vn.ute_forum.model.Request;
import nvt.vn.ute_forum.model.Users;
import nvt.vn.ute_forum.repository.NotificationRepo;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.UUID;

@Service
public class NotificationService {

    @Autowired
    private NotificationRepo notificationRepo;

    public List<Notification> getByUserId(String userId) {
        return notificationRepo.findByUsers_IdOrderByCreateAtDesc(userId);
    }

    public long countUnreadByUserId(String userId) {
        return notificationRepo.countByUsers_IdAndIsReadFalse(userId);
    }

    public Optional<Notification> getByIdForUser(String notificationId, String userId) {
        return notificationRepo.findByIdAndUsers_Id(notificationId, userId);
    }

    public void markAsRead(Notification notification) {
        if (notification == null || Boolean.TRUE.equals(notification.getRead())) {
            return;
        }
        notification.setRead(true);
        notificationRepo.save(notification);
    }

    public void notifyForumComment(Users actor, Request request, String commentContent) {
        if (request == null || request.getUser() == null || actor == null) {
            return;
        }
        Users receiver = request.getUser();
        if (receiver.getId() != null && receiver.getId().equals(actor.getId())) {
            return;
        }

        String actorName = actor.getFullName() == null ? "Nguoi dung" : actor.getFullName();
        String requestSubject = request.getSubject() == null ? "bai viet" : request.getSubject();
        String safeComment = (commentContent == null || commentContent.isBlank()) ? "" : (": \"" + commentContent.trim() + "\"");

        upsertForumNotification(
                "COMMENT_FORUM_POST_NOTIFICATION",
                "Binh luan moi",
                actorName + " da binh luan tren bai viet \"" + requestSubject + "\"" + safeComment,
                request.getId(),
                receiver
        );
    }

    public void notifyForumVote(Users actor, Request request, ReactionType reactionType) {
        if (request == null || request.getUser() == null || actor == null || reactionType == null) {
            return;
        }
        Users receiver = request.getUser();
        if (receiver.getId() != null && receiver.getId().equals(actor.getId())) {
            return;
        }

        String actorName = actor.getFullName() == null ? "Nguoi dung" : actor.getFullName();
        String requestSubject = request.getSubject() == null ? "bai viet" : request.getSubject();

        upsertForumNotification(
                "VOTE_FORUM_POST_NOTIFICATION",
                "Tuong tac moi",
                actorName + " da tha cam xuc " + reactionType.name() + " cho bai viet \"" + requestSubject + "\"",
                request.getId(),
                receiver
        );
    }

    private void upsertForumNotification(String notificationType,
                                         String title,
                                         String content,
                                         String referenceId,
                                         Users receiver) {
        if (receiver == null || receiver.getId() == null || receiver.getId().isBlank()) {
            return;
        }

        Notification notification = notificationRepo.findByNotificationType(notificationType)
                .orElseGet(Notification::new);

        if (notification.getId() == null || notification.getId().isBlank()) {
            notification.setId("NTF_" + UUID.randomUUID());
        }

        notification.setNotificationType(notificationType);
        notification.setTitle(title);
        notification.setContent(content);
        notification.setReferenceId(referenceId);
        notification.setRead(false);
        notification.setCreateAt(LocalDate.now());

        List<Users> receivers = notification.getUsers();
        if (receivers == null) {
            receivers = new ArrayList<>();
            notification.setUsers(receivers);
        }

        boolean exists = receivers.stream()
                .anyMatch(user -> user != null && receiver.getId().equals(user.getId()));
        if (!exists) {
            receivers.add(receiver);
        }

        notificationRepo.save(notification);
    }


}

package nvt.vn.ute_forum.service;

import nvt.vn.ute_forum.model.Notification;
import nvt.vn.ute_forum.model.Announcement;
import nvt.vn.ute_forum.model.ReactionType;
import nvt.vn.ute_forum.model.Request;
import nvt.vn.ute_forum.model.Users;
import nvt.vn.ute_forum.repository.NotificationRepo;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Optional;
import java.util.UUID;

@Service
public class NotificationService {

    @Autowired
    private NotificationRepo notificationRepo;

    public List<Notification> getByUserId(String userId) {
        return notificationRepo.findByUsers_IdOrderByCreateAtDesc(userId);
    }

    public long countUnreadByUserId(String userId) {
        return notificationRepo.countByUsers_IdAndIsReadFalse(userId);
    }

    public Optional<Notification> getByIdForUser(String notificationId, String userId) {
        return notificationRepo.findByIdAndUsers_Id(notificationId, userId);
    }

    public void markAsRead(Notification notification) {
        if (notification == null || Boolean.TRUE.equals(notification.getRead())) {
            return;
        }
        notification.setRead(true);
        notificationRepo.save(notification);
    }

    public void notifyForumComment(Users actor, Request request, String commentContent) {
        if (request == null || request.getUser() == null || actor == null) {
            return;
        }
        Users receiver = request.getUser();
        if (receiver.getId() != null && receiver.getId().equals(actor.getId())) {
            return;
        }

        String actorName = actor.getFullName() == null ? "Nguoi dung" : actor.getFullName();
        String requestSubject = request.getSubject() == null ? "bai viet" : request.getSubject();
        String safeComment = (commentContent == null || commentContent.isBlank()) ? "" : (": \"" + commentContent.trim() + "\"");

        upsertForumNotification(
                "COMMENT_FORUM_POST_NOTIFICATION",
                "Binh luan moi",
                actorName + " da binh luan tren bai viet \"" + requestSubject + "\"" + safeComment,
                request.getId(),
                receiver
        );
    }

    public void notifyForumVote(Users actor, Request request, ReactionType reactionType) {
        if (request == null || request.getUser() == null || actor == null || reactionType == null) {
            return;
        }
        Users receiver = request.getUser();
        if (receiver.getId() != null && receiver.getId().equals(actor.getId())) {
            return;
        }

        String actorName = actor.getFullName() == null ? "Nguoi dung" : actor.getFullName();
        String requestSubject = request.getSubject() == null ? "bai viet" : request.getSubject();

        upsertForumNotification(
                "VOTE_FORUM_POST_NOTIFICATION",
                "Tuong tac moi",
                actorName + " da tha cam xuc " + reactionType.name() + " cho bai viet \"" + requestSubject + "\"",
                request.getId(),
                receiver
        );
    }

    public void notifyNewAnnouncement(Announcement announcement, List<Users> receivers) {
        if (announcement == null) {
            return;
        }

        List<Users> distinctReceivers = distinctUsers(receivers);
        if (distinctReceivers.isEmpty()) {
            return;
        }

        String title = (announcement.getTitle() == null || announcement.getTitle().isBlank())
                ? "Thong bao moi"
                : announcement.getTitle().trim();

        String content = "Co thong bao moi" + (announcement.getTitle() == null || announcement.getTitle().isBlank()
                ? "."
                : ": \"" + announcement.getTitle().trim() + "\".");

        upsertAnnouncementNotification(
                "NEW_ANNOUNCEMENT_NOTIFICATION",
                title,
                content,
                announcement.getId(),
                distinctReceivers
        );
    }

    private void upsertForumNotification(String notificationType,
                                         String title,
                                         String content,
                                         String referenceId,
                                         Users receiver) {
        if (receiver == null || receiver.getId() == null || receiver.getId().isBlank()) {
            return;
        }

        Notification notification = notificationRepo.findByNotificationType(notificationType)
                .orElseGet(Notification::new);

        if (notification.getId() == null || notification.getId().isBlank()) {
            notification.setId("NTF_" + UUID.randomUUID());
        }

        notification.setNotificationType(notificationType);
        notification.setTitle(title);
        notification.setContent(content);
        notification.setReferenceId(referenceId);
        notification.setRead(false);
        notification.setCreateAt(LocalDate.now());

        List<Users> receivers = notification.getUsers();
        if (receivers == null) {
            receivers = new ArrayList<>();
            notification.setUsers(receivers);
        }

        boolean exists = receivers.stream()
                .anyMatch(user -> user != null && receiver.getId().equals(user.getId()));
        if (!exists) {
            receivers.add(receiver);
        }

        notificationRepo.save(notification);
    }

    private void upsertAnnouncementNotification(String notificationType,
                                                String title,
                                                String content,
                                                String referenceId,
                                                List<Users> receivers) {
        Notification notification = notificationRepo.findByNotificationType(notificationType)
                .orElseGet(Notification::new);

        if (notification.getId() == null || notification.getId().isBlank()) {
            notification.setId("NTF_" + UUID.randomUUID());
        }

        notification.setNotificationType(notificationType);
        notification.setTitle(title);
        notification.setContent(content);
        notification.setReferenceId(referenceId);
        notification.setRead(false);
        notification.setCreateAt(LocalDate.now());
        notification.setUsers(new ArrayList<>(receivers));

        notificationRepo.save(notification);
    }

    private List<Users> distinctUsers(List<Users> users) {
        if (users == null || users.isEmpty()) {
            return List.of();
        }

        LinkedHashMap<String, Users> deduplicated = new LinkedHashMap<>();
        for (Users user : users) {
            if (user != null && user.getId() != null && !user.getId().isBlank()) {
                deduplicated.putIfAbsent(user.getId(), user);
            }
        }
        return new ArrayList<>(deduplicated.values());
    }


}

