}

.sidebar-nav {
    margin-top: 10px;
    padding: 0 10px;
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.nav-item {
    text-decoration: none;
    color: #dbe7ff;
    padding: 10px 12px;
    border-radius: 10px;
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: 15px;
    font-weight: 500;
}

.nav-item:hover,
.nav-item.active {
    background: rgba(255, 255, 255, 0.16);
    color: #fff;
}

.badge-count {
    margin-left: auto;
    min-width: 20px;
    height: 20px;
    border-radius: 50px;
    background: #ef233c;
    font-size: 12px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 0 6px;
}

.logout-btn {
    margin-top: auto;
    color: #fff;
    text-decoration: none;
    padding: 14px 16px;
    border-top: 1px solid rgba(255, 255, 255, 0.16);
    font-size: 15px;
}

.main-content {
    padding: 10px 36px 20px;
}

.page-head h1 {
    margin: 0;
    font-size: 56px;
    line-height: 1.05;
}

.page-head p {
    margin: 8px 0 0;
    color: #475569;
    font-size: 18px;
}

.forum-tabs {
    margin-top: 14px;
    display: flex;
    gap: 10px;
}

.tab-item {
    border: 1px solid #cbd5e1;
    border-radius: 999px;
    background: #fff;
    padding: 10px 22px;
    font-size: 16px;
    font-weight: 600;
    color: #334155;
    text-decoration: none;
    display: inline-flex;
    align-items: center;
    gap: 10px;
}

.tab-item.active {
    background: #0f1f43;
    color: #fff;
    border-color: #0f1f43;
}

.content-grid {
    margin-top: 16px;
    display: grid;
    grid-template-columns: minmax(0, 1fr) 310px;
    gap: 20px;
    align-items: start;
}

.post-list {
    display: flex;
    flex-direction: column;
    gap: 18px;
}

.discussion-card,
.announcement-card {
    background: #fff;
    border: 1px solid #dbe3ef;
    border-radius: 16px;
    padding: 18px 24px;
    box-shadow: 0 1px 2px rgba(15, 23, 42, 0.08);
}

.discussion-head,
.announcement-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
}

.author-wrap,
.dept-wrap {
    display: flex;
    align-items: center;
    gap: 10px;
}

.author-avatar,
.dept-icon {
    width: 38px;
    height: 38px;
    border-radius: 50%;
    background: #eef2f7;
    color: #64748b;
    display: inline-flex;
    align-items: center;
    justify-content: center;
}

.dept-icon {
    background: #fff4d9;
    color: #b07a16;
}

.author-name,
.dept-name {
    margin: 0;
    font-size: 18px;
    font-weight: 700;
}

.author-date,
.post-date {
    font-size: 14px;
    color: #8ca0bd;
}

.status-pill {
    background: #d9fbe4;
    color: #16a34a;
    border-radius: 10px;
    padding: 6px 10px;
    font-size: 15px;
    font-weight: 600;
    display: inline-flex;
    gap: 6px;
    align-items: center;
}

.discussion-title,
.announcement-title {
    margin: 14px 0 8px;
    font-size: 24px;
    line-height: 1.25;
}

.discussion-text,
.announcement-text {
    margin: 0;
    color: #475569;
    font-size: 15px;
    line-height: 1.5;
}

.announcement-text {
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
}

.tag-row {
    display: flex;
    gap: 8px;
    flex-wrap: wrap;
    margin-top: 14px;
}

.chip {
    background: #f1f5f9;
    color: #475569;
    border-radius: 10px;
    padding: 7px 10px;
    font-size: 13px;
    display: inline-flex;
    align-items: center;
    gap: 6px;
}

.discussion-actions {
    margin-top: 14px;
    padding-top: 14px;
    border-top: 1px solid #e5eaf2;
    display: flex;
    gap: 28px;
    color: #475569;
    font-size: 13px;
}

.announcement-actions {
    margin-top: 14px;
    padding-top: 14px;
    border-top: 1px solid #e5eaf2;
    display: flex;
    align-items: center;
    gap: 12px;
    justify-content: flex-end;
}

.action-link {
    border: none;
    background: transparent;
    color: #1d4ed8;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    text-decoration: none;
    padding: 0;
}

.delete-link {
    color: #dc2626;
}

.edit-form {
    margin-top: 12px;
    border-top: 1px dashed #dbe3ef;
    padding-top: 12px;
    display: none;
}

.edit-form.show {
    display: block;
}

.edit-textarea {
    width: 100%;
    border: 1px solid #cbd5e1;
    border-radius: 10px;
    padding: 10px 12px;
    font-size: 14px;
    font-family: inherit;
    min-height: 110px;
    resize: vertical;
    background: #f8fafc;
}

.edit-actions {
    margin-top: 10px;
    display: flex;
    align-items: center;
    gap: 12px;
}

.receiver-checkbox-list {
    margin-top: 6px;
    max-height: 180px;
    overflow-y: auto;
    border: 1px solid #cbd5e1;
    border-radius: 10px;
    background: #f8fafc;
    padding: 8px 10px;
}

.receiver-select-all {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 14px;
    color: #1e293b;
    font-weight: 600;
    margin-bottom: 8px;
}

.receiver-checkbox-item {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 14px;
    color: #334155;
    padding: 5px 0;
}

.detail-link {
    color: #2563eb;
    text-decoration: none;
    font-size: 16px;
    font-weight: 700;
    display: inline-flex;
    align-items: center;
    gap: 8px;
}

.right-panel {
    display: flex;
    flex-direction: column;
    gap: 14px;
}

.widget {
    background: #fff;
    border: 1px solid #dbe3ef;
    border-radius: 16px;
    padding: 16px;
}

.widget h3 {
    margin: 0 0 12px;
    font-size: 20px;
    display: flex;
    align-items: center;
    gap: 8px;
}

.search-input,
.widget select {
    width: 100%;
    height: 42px;
    border: 1px solid #cbd5e1;
    border-radius: 10px;
    padding: 0 12px;
    font-size: 14px;
    background: #f8fafc;
}

.widget-label {
    display: block;
    margin: 10px 0 6px;
    font-size: 14px;
    color: #64748b;
}

.create-btn {
    border: none;
    background: #2f5fff;
    color: #fff;
    border-radius: 14px;
    height: 48px;
    font-size: 18px;
    font-weight: 700;
    cursor: pointer;
    text-decoration: none;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
}

.empty-state {
    background: #fff;
    border: 1px dashed #cbd5e1;
    border-radius: 14px;
    padding: 24px;
    text-align: center;
    color: #64748b;
}

.pagination {
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 10px;
}

.page-btn {
    text-decoration: none;
    color: #1d4ed8;
    border: 1px solid #bfdbfe;
    border-radius: 8px;
    padding: 6px 10px;
    background: #eff6ff;
}

@media (max-width: 1200px) {
    .content-grid {
        grid-template-columns: 1fr;
    }
}
